// PWA da Ecobraz — deixa os apps (Operação e Coletas) instaláveis ("adicionar à tela inicial"):
// abrem em tela cheia, com ícone próprio, e já logados. Sem loja de apps.
// Manifesto dinâmico por app (?app=operacao|agente), service worker mínimo e ícones embutidos.

const ICON_192 = '';
const ICON_512 = '';
function b64ParaBytes(b64){ const bin=atob(b64); const out=new Uint8Array(bin.length); for(let i=0;i<bin.length;i++) out[i]=bin.charCodeAt(i); return out; }
export function servirIcone(qual){
  const b64 = qual === '512' ? ICON_512 : ICON_192;
  return new Response(b64ParaBytes(b64), { headers: { 'content-type': 'image/png', 'cache-control': 'public, max-age=604800' } });
}

const APPS = {
  operacao: { name: 'Ecobraz Operação', short: 'Operação', start: '/operacao' },
  agente:   { name: 'Ecobraz Coletas',  short: 'Coletas',  start: '/agente' },
};
export function servirManifest(url){
  const app = APPS[url.searchParams.get('app')] || APPS.operacao;
  const m = {
    name: app.name, short_name: app.short, start_url: app.start, scope: '/',
    display: 'standalone', background_color: '#00333B', theme_color: '#00333B', lang: 'pt-BR',
    icons: [
      { src: '/assets/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any maskable' },
      { src: '/assets/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any maskable' },
    ],
  };
  return new Response(JSON.stringify(m), { headers: { 'content-type': 'application/manifest+json; charset=utf-8', 'cache-control': 'no-cache' } });
}
export function servirServiceWorker(){
  // SW mínimo: habilita a instalação e serve o app mesmo com rede instável (cai pra rede sempre).
  const js = `self.addEventListener('install',e=>self.skipWaiting());
self.addEventListener('activate',e=>self.clients.claim());
self.addEventListener('fetch',e=>{});`;
  return new Response(js, { headers: { 'content-type': 'application/javascript; charset=utf-8', 'cache-control': 'no-cache' } });
}
// Tags a colocar no <head> de cada app para virar PWA instalável.
export function tagsPWA(app){
  return '<link rel="manifest" href="/manifest.webmanifest?app=' + app + '">' +
    '<meta name="theme-color" content="#00333B">' +
    '<meta name="mobile-web-app-capable" content="yes">' +
    '<meta name="apple-mobile-web-app-capable" content="yes">' +
    '<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">' +
    '<meta name="apple-mobile-web-app-title" content="Ecobraz">' +
    '<link rel="apple-touch-icon" href="/assets/icon-192.png">' +
    '<script>if("serviceWorker"in navigator){addEventListener("load",()=>navigator.serviceWorker.register("/sw.js").catch(()=>{}))}</script>';
}
